package schema

func BusinessConfigTableDefinitions() []string {
	return []string{
		`CREATE TABLE IF NOT EXISTS business_definitions (id UUID PRIMARY KEY,kind TEXT NOT NULL,key TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',schema JSONB NOT NULL DEFAULT '{}',settings JSONB NOT NULL DEFAULT '{}',status TEXT NOT NULL CHECK(status IN ('draft','active','archived')),revision INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(kind,key))`,
		`CREATE TABLE IF NOT EXISTS business_definition_revisions (definition_id UUID NOT NULL REFERENCES business_definitions(id),revision INTEGER NOT NULL,document JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(definition_id,revision))`,
		`CREATE TABLE IF NOT EXISTS customer_external_id_aliases (external_user_id TEXT PRIMARY KEY,customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`,
		`CREATE TABLE IF NOT EXISTS business_objects (id UUID PRIMARY KEY,object_type TEXT NOT NULL,source TEXT NOT NULL,external_key TEXT NOT NULL,customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE CASCADE,attributes JSONB NOT NULL DEFAULT '{}',definition_revision INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(object_type,source,external_key))`,
		`CREATE INDEX IF NOT EXISTS idx_business_objects_customer ON business_objects(customer_id,object_type)`,
		`CREATE TABLE IF NOT EXISTS business_object_relations (id UUID PRIMARY KEY,relation_key TEXT NOT NULL,from_id UUID NOT NULL REFERENCES business_objects(id) ON DELETE CASCADE,to_id UUID NOT NULL REFERENCES business_objects(id) ON DELETE CASCADE,valid_from TIMESTAMPTZ NOT NULL DEFAULT NOW(),valid_to TIMESTAMPTZ,UNIQUE(relation_key,from_id,to_id),CHECK(from_id<>to_id))`,
		`CREATE TABLE IF NOT EXISTS customer_attribute_values (customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE CASCADE,attribute_key TEXT NOT NULL,value JSONB NOT NULL,definition_revision INTEGER NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(customer_id,attribute_key))`,
		`INSERT INTO business_definitions(id,kind,key,name,schema,settings,status) SELECT md5('business:event:'||v.code)::uuid,'event',v.code,v.name,'{"type":"object"}'::jsonb,'{"builtin":true,"subject_type":"customer","expiry_mode":"never","browser_enabled":false}'::jsonb,'active' FROM (VALUES ('contact.created','Customer created'),('contact.updated','Customer updated'),('email.sent','Email sent'),('email.delivered','Email delivered'),('email.opened','Email opened'),('email.clicked','Email clicked'),('email.bounced','Email bounced'),('email.complained','Email complained'),('email.unsubscribed','Email unsubscribed')) AS v(code,name) ON CONFLICT(kind,key) DO NOTHING`,
		`INSERT INTO business_definitions(id,kind,key,name,schema,settings,status) SELECT md5('business:event:'||v.code)::uuid,'event',v.code,v.name,'{"type":"object"}'::jsonb,'{"builtin":true,"subject_type":"any","expiry_mode":"never","browser_enabled":false,"allowed_sources":["platform.state_projector"]}'::jsonb,'active' FROM (VALUES ('state.entered','State entered'),('state.exited','State exited')) AS v(code,name) ON CONFLICT(kind,key) DO NOTHING`,
		`INSERT INTO business_definitions(id,kind,key,name,schema,settings,status) SELECT md5('business:attribute:'||v.code)::uuid,'customer_attribute',v.code,v.name,'{"type":"string"}'::jsonb,'{"identity":true,"sensitive":true,"writable":false}'::jsonb,'active' FROM (VALUES ('external_user_id','External user ID'),('email','Email address'),('phone','Phone number')) AS v(code,name) ON CONFLICT(kind,key) DO NOTHING`,
		`INSERT INTO business_definition_revisions(definition_id,revision,document) SELECT id,revision,to_jsonb(d) FROM business_definitions d ON CONFLICT(definition_id,revision) DO NOTHING`,
		nativeBusinessEventSeed(),
		`INSERT INTO business_definition_revisions(definition_id,revision,document) SELECT id,revision,to_jsonb(d) FROM business_definitions d ON CONFLICT(definition_id,revision) DO NOTHING`,
	}
}
